<script setup>import{onMounted,ref}from'vue';import{RefreshCw,ShieldCheck,Undo2}from'@lucide/vue';import{getM6EnterpriseWorkspace}from'../api/m6';import{decideMultilevelReview,getMultilevelQueue}from'../api/multilevelReview';const org=ref(''),items=ref([]),selected=ref(null),error=ref(''),busy=ref(false),reason=ref('当前层级证据与责任边界检查通过');async function load(){try{if(!org.value){const x=await getM6EnterpriseWorkspace();org.value=x.selected?.organization_id||x.organizations?.[0]?.id||''}if(org.value){items.value=(await getMultilevelQueue(org.value)).items;selected.value=items.value.find(x=>x.id===selected.value?.id)||items.value[0]||null}}catch(e){error.value=e.detail||'加载失败'}}async function act(action){busy.value=true;try{selected.value=await decideMultilevelReview(selected.value.id,{action,reason:reason.value,expected_version:selected.value.lock_version});await load()}catch(e){error.value=e.detail||'操作失败'}finally{busy.value=false}}onMounted(load)</script>
<template><main class="review-page"><header><div><p>MULTI-LEVEL REVIEW</p><h2>多级演示审核队列</h2><span>一级评审、二级复核、最终签核的角色分离责任链</span></div><button aria-label="刷新多级审核" @click="load"><RefreshCw :size="16"/></button></header><div class="notice"><ShieldCheck :size="16"/><span>演示角色审核流程，不代表外部专家认证；同一账号不得批准多个层级。</span></div><p v-if="error" class="error">{{error}}</p><section class="layout"><div class="list"><button v-for="x in items" :key="x.id" :class="{active:selected?.id===x.id}" @click="selected=x"><strong>{{x.object_type}} · {{x.object_id}}</strong><span>{{x.object_version}} · {{x.status}}</span></button><p v-if="!items.length">暂无审核案件</p></div><div v-if="selected" class="detail"><div class="title"><div><h3>{{selected.object_id}}</h3><span>当前层级 {{selected.current_level}} · 版本 {{selected.lock_version}}</span></div><em>{{selected.status}}</em></div><pre>{{JSON.stringify(selected.evidence_snapshot,null,2)}}</pre><div v-if="selected.status.includes('pending')" class="actions"><input v-model="reason" aria-label="审核理由"/><button :disabled="busy" @click="act('approve')"><ShieldCheck :size="14"/>批准当前层级</button><button class="return" :disabled="busy" @click="act('return')"><Undo2 :size="14"/>退回</button></div><h3>不可变责任时间线</h3><div v-for="d in selected.decisions" :key="d.id" class="event"><div><strong>L{{d.level}} {{d.action}} · {{d.from_status}} → {{d.to_status}}</strong><span>{{d.actor_role}} · {{d.actor_public_id}} · {{d.reason}}</span></div><em>{{d.created_at}}</em></div></div></section></main></template>
<style scoped>.review-page{max-width:1180px;margin:0 auto;color:#27322c}header,.notice,.title,.actions,.event{display:flex;align-items:center}header{justify-content:space-between}header p{margin:0;color:#718078;font-size:10px;font-weight:800;letter-spacing:.12em}h2{margin:4px 0;font-size:24px}header span,.event span,.title span{color:#7b8980;font-size:10px}header button{display:grid;width:36px;height:36px;place-items:center;border:1px solid #dce5de;border-radius:7px;background:#fff}.notice{gap:8px;margin:14px 0;padding:11px;border-left:3px solid #c8a75d;background:#fff9ef;font-size:11px}.layout{display:grid;grid-template-columns:320px minmax(0,1fr);gap:10px}.list,.detail{min-width:0;padding:12px;border:1px solid #dfe7e1;border-radius:8px;background:#fff}.list button{display:block;width:100%;padding:11px;border:0;border-bottom:1px solid #e8eee9;background:transparent;text-align:left}.list button.active{background:#f0f6f2}.list strong,.list span{display:block;font-size:11px}.list span{margin-top:4px;color:#819087}.title{justify-content:space-between}.title h3{margin:0}.title em{padding:4px 7px;background:#eef5ef;font-size:10px;font-style:normal}.detail pre{max-height:160px;overflow:auto;padding:10px;background:#f5f7f5;font:10px/1.5 Consolas,monospace;white-space:pre-wrap}.actions{gap:7px;margin:12px 0}.actions input{min-width:0;flex:1;padding:8px;border:1px solid #dce5de;border-radius:6px}.actions button{display:flex;align-items:center;gap:5px;padding:8px;border:0;border-radius:6px;background:#304238;color:#fff}.actions .return{background:#8c5c50}.event{justify-content:space-between;gap:10px;padding:10px;border-top:1px solid #e8eee9}.event strong{font-size:11px}.event em{flex:0 0 auto;color:#7d8981;font-size:9px;font-style:normal}.error{padding:9px;background:#fff2f0;color:#974d44}@media(max-width:760px){.layout{grid-template-columns:1fr}.actions,.event{align-items:flex-start;flex-direction:column}.actions input{width:100%;box-sizing:border-box}.event em{align-self:flex-start}}</style>
